func TestAuthStatusAgentNoCredentialsIsStructuredBlockedJSON(t *testing.T) {
	t.Setenv("CLOUDFLARE_API_TOKEN", "")

	var flags rootFlags
	root := newRootCmd(&flags)
	var stdout, stderr bytes.Buffer
	root.SetOut(&stdout)
	root.SetErr(&stderr)
	root.SetArgs([]string{"auth", "status", "--agent", "--config", filepath.Join(t.TempDir(), "config.toml")})

	if err := root.Execute(); err != nil {
		t.Fatalf("auth status --agent with no credentials should return structured blocked JSON without a cobra error, got: %v", err)
	}
	if stderr.Len() != 0 {
		t.Fatalf("stderr = %q, want empty so --agent output remains parseable JSON", stderr.String())
	}
	var out map[string]any
	if err := json.Unmarshal(stdout.Bytes(), &out); err != nil {
		t.Fatalf("stdout is not JSON: %v; raw=%q", err, stdout.String())
	}
	if out["authenticated"] != false {
		t.Fatalf("authenticated = %#v, want false", out["authenticated"])
	}
	if out["blocked"] != true {
		t.Fatalf("blocked = %#v, want true", out["blocked"])
	}
	if out["error"] != "no credentials configured" {
		t.Fatalf("error = %#v, want no credentials configured", out["error"])
	}
	hint, ok := out["hint"].(string)
	if !ok || !strings.Contains(hint, "cloudflare-pp-cli auth setup") {
		t.Fatalf("hint = %#v, want auth setup instructions", out["hint"])
	}
}

